import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Listen,
	Prop,
	h,
} from "@stencil/core";
import retargetEvents from "react-shadow-dom-retarget-events";
import { getLegends } from "../../../utils/charts";
import { renderChart } from "./RenderChart";
import { layers } from "./layers/layers";
import { customTooltipFn } from "./utils/CustomTooltip";
import { updateConfig } from "./utils/config";
import { barResetSelected, barSelectState, resetStyles } from "./utils/util";

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
	tag: "hbr-bar",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrBarCohesion {
	barchart: HTMLElement;

	/** Chart configuration object. Refer to https://nivo.rocks/bar */
	@Prop({ mutable: true }) config: any;
	/** Chart variant like compact version: show label above the bar */
	@Prop() variant: string;
	/** Customized above-the-bar-label {variant: "link", additional: array of additional text objects} */
	@Prop() compactLabel: Object;
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";
	/** Show tooltip on tick label hover */
	@Prop() tickLabelTooltip = true;
	/** Show tooltip on legend hover */
	@Prop() legendTooltip = true;
	/** Background threshold level */
	@Prop() threshold: number;
	/** disable the first legend when only one data set */
	@Prop() noFirstLegend = true;

	@Element() private el: HTMLHbrBarElement;

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;

	private grouped = false;
	private stacked = false;
	axesupdate: boolean;
	private original: object;
	private isvertical = true;

	componentDidLoad() {
		this.createChart();
		retargetEvents(this.el.shadowRoot);
		setTimeout(() => {
			/** can't pass func through componentFromHTMLString so listen for the click and emit to users */
			const linkLabels = this.barchart.querySelectorAll(
				".--label-above-link",
			) as NodeListOf<HTMLElement>;
			if (linkLabels?.length) {
				Array.from(linkLabels).forEach((linkLabel) =>
					linkLabel.addEventListener("click", (evt) =>
						this.abovebarlabelOnClick(linkLabel, evt),
					),
				);
			}
		});
	}

	componentShouldUpdate() {
		return this.createChart();
	}

	/** Emitted when  a label above a bar is clicked */
	@Event({ eventName: "hbr-above-barlabel-click" })
	hbrAboveBarlabelClick: EventEmitter;
	abovebarlabelOnClick(el, evt) {
		this.hbrAboveBarlabelClick.emit({
			event: evt,
			indexvalue: el.dataset.indexvalue,
		});
	}

	@Listen("click", { passive: true })
	handleOutsideClick(evt) {
		const { grouped } = this;
		const path = evt.path || evt.composedPath?.();
		if (path?.length) {
			const firstItemOnPath = path[0];
			const parentItem = firstItemOnPath.parentElement;
			let legendClick;
			const barClick =
				firstItemOnPath.parentElement?.classList.contains("--bar");
			if (grouped) {
				legendClick =
					firstItemOnPath.tagName === "rect" &&
					firstItemOnPath.nextElementSibling &&
					firstItemOnPath.nextElementSibling.tagName === "circle" &&
					firstItemOnPath.nextElementSibling.nextElementSibling &&
					firstItemOnPath.nextElementSibling.nextElementSibling.tagName ===
						"text";
			}

			if (!legendClick) {
				resetStyles.call(this, grouped, firstItemOnPath);
				if (this.barchart.querySelector("[data-legend-selected-items]")) {
					barResetSelected.call(this, "legend");
				}
				if (
					!barClick &&
					this.barchart.querySelector("g.--bar.--bar--not-selected")
				) {
					barSelectState.call(this, parentItem);
				}
			}
		}
	}

	verticalFn = (layout) => !layout || layout === "vertical";

	createChart() {
		const { config } = this;
		const { groupMode, layout } = config;
		if (!this.axesupdate) {
			const _layout = layout ? layout : "vertical";
			this.isvertical = this.verticalFn(_layout);
			if (groupMode) {
				this.grouped = groupMode === "grouped";
				this.stacked = groupMode === "stacked";
			}
			customTooltipFn.call(this, config);
			updateConfig.call(this, config);
			this.keepOriginal(config);
		}

		if (config.legends === undefined || config.legends?.length) {
			// skip if legends is null or []
			config.legends = getLegends(config, config.margin, "bar");
		}
		if (!config.layers || !Array.isArray(config.layers)) {
			// skip if layers is Array.
			config.layers = layers.call(
				this,
				config,
				getLegends(config, config.margin, "bar"),
			);
		}

		this.contextRoot = renderChart({
			el: this.barchart,
			config,
			threshold: this.threshold,
			contextRoot: this.contextRoot,
		});
	}

	keepOriginal = (config) => {
		const { grouped, original } = this;
		if (grouped && !original) {
			/** may modified on legend click */
			this.original = {
				maxValue: config.maxValue,
				gridYValues: config.gridYValues,
			};
		}
	};

	labesOnBar = () => {
		const lablesIn = this.barchart.querySelectorAll(
			".--layer-inBar",
		) as NodeListOf<HTMLElement>;
		const lablesAbove = this.barchart.querySelectorAll(
			".--layer-aboveBar",
		) as NodeListOf<HTMLElement>;
		let labelsInArr;
		let labelsAboveArr;
		if (lablesIn?.length) {
			labelsInArr = Array.from(lablesIn);
		}
		if (lablesAbove?.length) {
			labelsAboveArr = Array.from(lablesAbove);
		}
		return {
			labelsInBar: labelsInArr,
			labelsAboveBar: labelsAboveArr,
		};
	};

	labelContnainerFn = (gFirstChild, labelLine, labelText) =>
		gFirstChild.tagName === "g" &&
		labelLine.tagName === "line" &&
		labelText.tagName === "text";

	variablesObj = (index, obj) => {
		const { isvertical } = this;
		const { data, gridXValues, newGridYValues, indexBy, tickText } = obj;
		const dataLen = data?.length;
		const dataLabel = dataLen && index < dataLen ? data[index][indexBy] : "";
		const xValues = gridXValues?.length;
		const yValues = newGridYValues?.length;
		const gridValues = isvertical
			? yValues && newGridYValues
			: xValues && gridXValues;
		const dataValue = gridValues?.[index];
		return {
			dataLabel,
			dataValue,
			gridValues,
			isXAxis: tickText && dataLabel && tickText === dataLabel,
		};
	};

	singleBarFn = () => !this.stacked && !this.grouped;

	render() {
		const { config } = this;
		const { groupMode } = config;
		const layout = config.layout ? config.layout : "vertical";
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		return (
			<Host>
				<div
					id="root"
					style={{ width: this.width, height: this.height }}
					ref={(el) => (this.barchart = el)}
					class={`--hbr-chart --bar-chart --bar-${layout}${
						groupMode === "stacked"
							? " --bar--stacked"
							: groupMode === "grouped"
							  ? " --bar--grouped"
							  : ""
					}`}
				/>
			</Host>
		);
	}
}
