import componentFromHTMLString from "../../../../utils/componentFromHTMLString";

export function customTooltipFn(config) {
	const { isInteractive, tooltip, groupMode, keys, tooltipFormat } = config;
	const containsNoData =
		!groupMode && keys.length === 2; /** single with no data */

	if (
		(isInteractive === undefined || isInteractive) &&
		!tooltip &&
		containsNoData
	) {
		config.tooltip = ({ id, value }) => {
			if (id !== keys[1]) {
				return componentFromHTMLString(
					`
          <div class="tooltip-content">
            <span class="tooltip-content-value">
              ${id}: <strong>${tooltipFormat ? tooltipFormat(value) : value}</strong>
            </span>
          </div>`,
					"html",
					{
						className: "chart--custom-tooltip --single",
					},
				);
			}
			return componentFromHTMLString(
				`
        <div class="tooltip-content">
          ${id}
        </div>`,
				"html",
				{
					className: "chart--custom-tooltip --single",
				},
			);
		};
		return config.tooltip;
	}
}
