import { ResponsiveBar as Bar } from "@harbor-charts/bar";
import merge from "deepmerge";
import React from "react";
import { createRoot } from "react-dom/client";
import { getBaseConfig } from "../../../utils/charts";
import { combineMergeArray } from "../../../utils/combineMergeArray";
import { barColors } from "./utils/barColors";

interface BasicConfig {
	margin?: object;
	padding?: number;
	valueScale: object;
	indexScale: object;
	borderColor?: object;
	motionStiffness: number;
	motionDamping: number;
	defs?: Array<object>;
	fill?: Array<object>;
	axisBottom?: object;
	axisLeft?: object;
	enableGridX?: boolean;
	enableGridY?: boolean;
	legends?: Array<object>;
	theme?: object;
	colors?: Array<string>;
	labelTextColor?: string;
	labelSkipWidth: number;
	markers?: Array<object>;
	groupMode?: string;
	onMouseEnter: Function;
	onMouseLeave: Function;
	onClick: Function;
}

function getBarBaseConfig(config, threshold) {
	const isThreshold = threshold && typeof threshold === "number";
	const basicConfig: BasicConfig = {
		padding: 0.5,
		valueScale: {
			type: "linear",
		},
		indexScale: {
			type: "band",
			round: true,
		},
		borderColor: {
			from: "color",
			modifiers: [["darker", 1.6]],
		},
		motionStiffness: 90,
		motionDamping: 15,
		labelTextColor: "var(--hbr-color-neutral-bg)",
		labelSkipWidth: 16,
		colors: barColors(config),
		onMouseEnter: (props, evt) => {
			const { currentTarget } = evt;
			const root = currentTarget.closest("svg") as HTMLElement;

			if (root) {
				const nullBar =
					config._nulldataColor &&
					root.querySelector(
						`svg > g > g> rect[fill='${config._nulldataColor}']`,
					);
				if (nullBar && nullBar === currentTarget) {
					currentTarget.style.cursor = "not-allowed";
				} else {
					const barRects = root.querySelectorAll(
						"svg > g > g > rect[fill]",
					) as NodeListOf<SVGElement>; //make sure filter out legends
					Array.from(barRects).forEach((bar) => {
						const parent = bar.parentElement;
						if (parent) {
							parent.classList?.add("--bar");
							if (bar !== currentTarget) {
								parent.classList?.add("--bar--dehighlight");
							}
						}
					});
				}
			}
			if (config.onMouseEnter) {
				config.onMouseEnter(props, evt);
			}
		},
		onMouseLeave: (props, evt) => {
			const { currentTarget } = evt;
			const root = currentTarget.closest("svg") as HTMLElement;
			if (root) {
				const barRects = root.querySelectorAll(
					"svg > g > g > rect[fill]",
				) as NodeListOf<SVGElement>; //make sure filter out legends
				Array.from(barRects).forEach((bar) => {
					const parent = bar.parentElement;
					if (parent) {
						parent.classList.remove("--bar--dehighlight");
					}
				});
			}
			if (config.onMouseLeave) {
				config.onMouseLeave(props, evt);
			}
		},
		onClick: (props, evt) => {
			const { currentTarget } = evt;
			const root = currentTarget.closest("svg") as HTMLElement;
			if (root && props.color !== config._nulldataColor) {
				const barRects = root.querySelectorAll(
					"svg > g > g > rect[fill]",
				) as NodeListOf<SVGElement>; //make sure filter out legends
				Array.from(barRects).forEach((bar) => {
					const parent = bar.parentElement;
					if (parent) {
						parent.classList.remove("--bar--selected", "--bar--not-selected");
						if (bar !== currentTarget) {
							parent.classList.add("--bar--not-selected");
						} else {
							parent.classList.add("--bar--selected");
						}
					}
				});
			}
			if (config.onClick) {
				config.onClick(props, evt);
			}
		},
	};

	const axisLeft = {
		tickValues: 3,
		tickSize: 0,
		tickPadding: 1.5,
		tickRotation: 0,
		legendPosition: "middle",
		legendOffset: -36,
	};
	const axisBottom = {
		tickSize: 0,
		tickPadding: 5,
		tickRotation: 0,
		legendPosition: "middle",
		legendOffset: 27,
	};

	if (config.groupMode) basicConfig.groupMode = config.groupMode;
	if (isThreshold) {
		basicConfig.markers = [
			{
				axis: "y",
				value: threshold,
				lineStyle: {
					stroke: "var(--hbr-color-on-surface, #545454)",
					strokeWidth: 1,
					strokeDasharray: "4, 2",
				},
			},
		];
	}
	config.colors = basicConfig.colors;

	if (config.layout && config.layout === "horizontal") {
		basicConfig.enableGridX = true;
		basicConfig.enableGridY = false;
	}

	if (config.axisLeft) {
		config.axisLeft = { ...axisLeft, ...config.axisLeft };
	}
	if (config.axisBottom) {
		config.axisBottom = { ...axisBottom, ...config.axisBottom };
	}
	return basicConfig;
}

export function renderChart({ el, config, threshold, contextRoot }: any) {
	const _config: any = merge.all(
		[getBaseConfig(), getBarBaseConfig(config, threshold), config],
		{
			arrayMerge: combineMergeArray,
		},
	);

	if (!el.innerHTML.length) {
		const newRoot = createRoot(el);
		newRoot.render(React.createElement(Bar, _config, null));
		return newRoot;
	}
	contextRoot.render(React.createElement(Bar, _config, null));
	return contextRoot;
}
