import componentFromHTMLString from "../../../../utils/componentFromHTMLString";

export function labelAboveBar(config, props) {
	const { bars } = props;
	const { _compactLabel } = config;
	const variant = _compactLabel?.variant;
	const additional = _compactLabel?.additional;
	const cls = `--label-above${
		variant && variant === "link" ? " --label-above-link" : ""
	}`;
	const PADDING_RIGHT = 6;
	const PADDING_BOTTOM = 5;
	const unique = [];
	const map = new Map();
	for (const item of bars) {
		if (!map.has(item.data.indexValue)) {
			map.set(item.data.indexValue, true); // set any value to Map
			unique.push(item);
		}
	}
	if (!additional) {
		return unique.map((_bar) => {
			return componentFromHTMLString(
				`<text class="${cls}" data-indexvalue="${_bar.data.indexValue}">${_bar.data.indexValue}</text>`,
				"svg",
				{
					key: _bar.key,
					className: "--layer-aboveBar",
					transform: `translate(${_bar.x + PADDING_RIGHT}, ${
						_bar.y - PADDING_BOTTOM
					})`,
				},
			);
		});
	}
	return unique.map((_bar) => {
		const found = additional.filter((d) => d.label === _bar.data.indexValue);
		let details = "";
		if (found?.length) {
			details = found[0].text;
		}

		return componentFromHTMLString(
			`<g transform="${`translate(${_bar.x + PADDING_RIGHT}, ${
				_bar.y - PADDING_BOTTOM
			})`}">
                    <text>
                        <tspan
                            class="${cls}"
                            data-indexvalue="${_bar.data.indexValue}"
                        >${_bar.data.indexValue}</tspan>
                        <tspan dx="10">${details}</tspan>
                    </text>
                    </g>`,
			"svg",
			{
				key: _bar.key,
				className: "--layer-aboveBar",
			},
		);
	});
}
