import React from "react";

interface ComponentFromHTMLStringProps {
	[key: string]: string | boolean | ((evt: MouseEvent) => void);
}

export default function componentFromHTMLString(
	str: string,
	type: "html" | "svg" = "html",
	props: ComponentFromHTMLStringProps = {},
): React.ReactElement {
	return React.createElement(
		type === "svg" ? "g" : "div",
		Object.assign({ dangerouslySetInnerHTML: { __html: str } }, props),
	);
}
