export function getContainer(evt) {
	let container = evt.relatedTarget;
	if (!container || !container.tagName || container.tagName !== "DIV") {
		container = evt.target.closest("svg").parentElement;
	}
	return container;
}

export function legendInteractionHover(evt, barRects, _data) {
	const container = getContainer(evt);
	if (container) {
		const root = evt.currentTarget.closest("svg") as HTMLElement;
		barRects = root.querySelectorAll(
			"svg > g > g > rect[fill]",
		) as NodeListOf<SVGElement>; //make sure filter out legends
		Array.from(barRects)
			.filter((p: SVGElement) => {
				if (_data.color.includes("var")) {
					const color = _data.color.split(",")[0];
					return !p.getAttribute("fill").includes(color);
				}
				return p.getAttribute("fill") !== _data.color;
			})
			.forEach((p: SVGElement) =>
				p.parentElement.classList.add("--bar", "--bar--dehighlight"),
			);
	}
	return barRects;
}
