import { barColors } from "../../components/chart-bar/cohesion/utils/barColors";
import { getColors } from "./";

export default function getLegends(config, margin, chartType) {
	let colors = Array.isArray(config.colors)
		? config.colors
		: getColors(config.data.length);
	if (typeof config.colors === "string") colors = [config.colors];
	let _data = [];
	if (chartType === "line") {
		_data = config.data.map((d, i) => ({
			color: colors[i],
			id: d.id,
			label: d.id,
		}));
	} else if (chartType === "bar") {
		if (typeof config.colors !== "string") colors = barColors(config);
		_data = config.keys.map((d, i) => ({
			color: colors[i],
			id: d,
			label: d,
		}));
	}

	const legends = [
		{
			dataFrom: "id",
			data: _data,
			anchor: "bottom-left",
			direction: "row",
			justify: false,
			translateX: 0,
			translateY: typeof margin?.top === "number" ? margin?.top * -1 : 0,
			itemsSpacing: 0,
			itemWidth: 80,
			itemDirection: "left-to-right",
			itemHeight: 20,
			itemOpacity: 1,
			symbolSize: 12,
			symbolShape: "circle",
			symbolBorderColor: "rgba(0, 0, 0, .5)",
			effects: [],
		},
	];
	if (!Array.isArray(config.data)) return [];
	if (config._variant === "small") return [];
	return legends;
}
